pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = -item_size as f64; // Penalize larger items to fill smaller bins more often
    score -= (bin_residual - mean_residual).abs() as f64 / bin_capacity as f64; // Favor bins closer to the global mean residual
    if step_index > 0 {
        score += (step_index as f64 / total_items as f64) * open_bins_count as f64; // Encourage spreading items across multiple bins earlier in the stream
    }
    if fitting_bins_count == 1 {
        score -= 0.5; // Penalize if this is the last chance to fit the item, encouraging early bin closure
    }
    if next_item_size > 0 && next_item_size < item_size * 2 {
        score += post_residual as f64 / bin_capacity as f64; // Reward for having enough space left in the current bin for future small items
    }
    score -= open_bins_count as f64 / mean_residual; // Penalize for each open bin relative to the global mean residual

    // Mutation: Incorporate a lookahead trade-off based on post-residual and next item size with a new factor
    if next_item_size > 0 && post_residual > next_item_size {
        score += (post_residual - next_item_size) as f64 / (bin_capacity * mean_residual); // Reward for having enough space to fit the next item without opening a new bin, normalized by capacity and mean residual
    }

    // Mutation: Penalize for high open bins count relative to post-residual
    if open_bins_count > 0 {
        score -= open_bins_count as f64 / (post_residual + 1); // Penalize for each open bin relative to the available space in the current bin
    }

    score
}

